<?php
namespace Modules\Ran\Reports;
class FinancePostingReport extends AbstractRanReport{public function title():string{return 'Finance Postings';}public function headings():array{return ['Source','Source ID','Posting','Debit Account','Credit Account','Amount','Status','Created'];}public function rows(array $f):array{$q=\DB::table('ran_finance_postings as f')->leftJoin('accounts as d','d.id','=','f.debit_account_id')->leftJoin('accounts as c','c.id','=','f.credit_account_id')->whereNull('f.deleted_at')->where('f.business_id',\Modules\Ran\Support\RanContext::businessId());if(!empty($f['date_from']))$q->whereDate('f.created_at','>=',$f['date_from']);if(!empty($f['date_to']))$q->whereDate('f.created_at','<=',$f['date_to']);return $q->orderByDesc('f.id')->get(['f.source_type','f.source_id','f.posting_type','d.name as debit_account','c.name as credit_account','f.amount','f.status','f.created_at'])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Amount'=>array_sum(array_column($rows,'amount'))];}}
